// ai_decode_attn.cu -- decode-phase single-query GQA attention CUDA kernel.
// Standalone program.
//
// Generated by ZCode/GLM (episode 30 AI drafting) from prompts/prompt-attention.md.
// No post-generation edits are allowed (experiment protocol).
//
// Semantics (Qwen3-0.6B dims): HQ=16, HKV=8, D=128 fixed.
//   q : [B, HQ, D];  k, v : [B, HKV, N, D];  o : [B, HQ, D]
//   kv = h / 2 (GQA);  s[t] = scale * (q . k[t]);  p = softmax(s) (stable);
//   o[h] = sum_t p[t] * v[t]
// One block per (batch, query head). Block threads = D = 128.
// Scores are staged in dynamic shared memory, then softmax weights written
// back in place; each thread owns one output dimension d.

#include <cuda_runtime.h>
#include <cuda_fp16.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>
#include <cmath>
#include <string>
#include <vector>

namespace {

constexpr int kHQ = 16;
constexpr int kHKV = 8;
constexpr int kD = 128;
constexpr float kScale = 0.08838834764831845f;  // 1/sqrt(128)
constexpr int kThreads = kD;                    // one thread per output dim

// ---------------------------------------------------------------------------
// Device reduction helpers
// ---------------------------------------------------------------------------

__inline__ __device__ float WarpReduceMax(float v) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        const float other = __shfl_xor_sync(0xffffffff, v, offset);
        v = fmaxf(v, other);
    }
    return v;
}

__inline__ __device__ float WarpReduceSum(float v) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        v += __shfl_xor_sync(0xffffffff, v, offset);
    }
    return v;
}

template <int BLOCK>
__inline__ __device__ float BlockReduceMax(float value) {
    constexpr int kWarps = BLOCK / 32;
    __shared__ float warp_max[kWarps];
    const int lane = threadIdx.x % 32;
    const int warp = threadIdx.x / 32;

    value = WarpReduceMax(value);
    if (lane == 0) warp_max[warp] = value;
    __syncthreads();

    if (warp == 0) {
        value = (lane < kWarps) ? warp_max[lane] : -INFINITY;
        value = WarpReduceMax(value);
    }
    return value;
}

template <int BLOCK>
__inline__ __device__ float BlockReduceSum(float value) {
    constexpr int kWarps = BLOCK / 32;
    __shared__ float warp_sums[kWarps];
    const int lane = threadIdx.x % 32;
    const int warp = threadIdx.x / 32;

    value = WarpReduceSum(value);
    if (lane == 0) warp_sums[warp] = value;
    __syncthreads();

    if (warp == 0) {
        value = (lane < kWarps) ? warp_sums[lane] : 0.0f;
        value = WarpReduceSum(value);
    }
    return value;
}

// ---------------------------------------------------------------------------
// Kernels
// ---------------------------------------------------------------------------

__global__ void DecodeAttnF32Kernel(const float* __restrict__ q,
                                    const float* __restrict__ k,
                                    const float* __restrict__ v,
                                    float* __restrict__ o,
                                    int batch, int kv_len) {
    extern __shared__ float s_scores[];  // kv_len floats

    const int b = blockIdx.x / kHQ;
    const int h = blockIdx.x % kHQ;
    const int kv = h / 2;  // GQA: 2 query heads share 1 kv head
    if (b >= batch) return;

    const float* qh = q + (static_cast<size_t>(b) * kHQ + h) * kD;
    const float* kh = k + ((static_cast<size_t>(b) * kHKV + kv) * kv_len) * kD;
    const float* vh = v + ((static_cast<size_t>(b) * kHKV + kv) * kv_len) * kD;

    // Phase 1: scores (thread t, t+BLOCK, ... ; serial 128-length dot each).
    for (int t = threadIdx.x; t < kv_len; t += kThreads) {
        const float* kt = kh + static_cast<size_t>(t) * kD;
        float dot = 0.0f;
#pragma unroll 8
        for (int d = 0; d < kD; ++d) {
            dot += qh[d] * kt[d];
        }
        s_scores[t] = kScale * dot;
    }
    __syncthreads();

    // Phase 2: block max over scores.
    float local_max = -INFINITY;
    for (int t = threadIdx.x; t < kv_len; t += kThreads) {
        local_max = fmaxf(local_max, s_scores[t]);
    }
    const float s_max = BlockReduceMax<kThreads>(local_max);
    __syncthreads();

    // Phase 3: exponentials in place + block sum.
    float local_sum = 0.0f;
    for (int t = threadIdx.x; t < kv_len; t += kThreads) {
        const float p = expf(s_scores[t] - s_max);
        s_scores[t] = p;
        local_sum += p;
    }
    const float s_sum = BlockReduceSum<kThreads>(local_sum);
    const float inv_sum = 1.0f / s_sum;
    __syncthreads();

    // Phase 4: write normalized weights back in place.
    for (int t = threadIdx.x; t < kv_len; t += kThreads) {
        s_scores[t] *= inv_sum;
    }
    __syncthreads();

    // Phase 5: weighted sum of V; thread d owns output dim d.
    const int d = threadIdx.x;
    float acc = 0.0f;
    for (int t = 0; t < kv_len; ++t) {
        acc += s_scores[t] * vh[static_cast<size_t>(t) * kD + d];
    }
    o[(static_cast<size_t>(b) * kHQ + h) * kD + d] = acc;
}

__global__ void DecodeAttnF16Kernel(const __half* __restrict__ q,
                                    const __half* __restrict__ k,
                                    const __half* __restrict__ v,
                                    __half* __restrict__ o,
                                    int batch, int kv_len) {
    extern __shared__ float s_scores[];  // kv_len floats (fp32 staging)

    const int b = blockIdx.x / kHQ;
    const int h = blockIdx.x % kHQ;
    const int kv = h / 2;
    if (b >= batch) return;

    const __half* qh = q + (static_cast<size_t>(b) * kHQ + h) * kD;
    const __half* kh = k + ((static_cast<size_t>(b) * kHKV + kv) * kv_len) * kD;
    const __half* vh = v + ((static_cast<size_t>(b) * kHKV + kv) * kv_len) * kD;

    for (int t = threadIdx.x; t < kv_len; t += kThreads) {
        const __half* kt = kh + static_cast<size_t>(t) * kD;
        float dot = 0.0f;
#pragma unroll 8
        for (int d = 0; d < kD; ++d) {
            dot += __half2float(qh[d]) * __half2float(kt[d]);
        }
        s_scores[t] = kScale * dot;
    }
    __syncthreads();

    float local_max = -INFINITY;
    for (int t = threadIdx.x; t < kv_len; t += kThreads) {
        local_max = fmaxf(local_max, s_scores[t]);
    }
    const float s_max = BlockReduceMax<kThreads>(local_max);
    __syncthreads();

    float local_sum = 0.0f;
    for (int t = threadIdx.x; t < kv_len; t += kThreads) {
        const float p = expf(s_scores[t] - s_max);
        s_scores[t] = p;
        local_sum += p;
    }
    const float s_sum = BlockReduceSum<kThreads>(local_sum);
    const float inv_sum = 1.0f / s_sum;
    __syncthreads();

    for (int t = threadIdx.x; t < kv_len; t += kThreads) {
        s_scores[t] *= inv_sum;
    }
    __syncthreads();

    const int d = threadIdx.x;
    float acc = 0.0f;
    for (int t = 0; t < kv_len; ++t) {
        acc += s_scores[t] * __half2float(vh[static_cast<size_t>(t) * kD + d]);
    }
    o[(static_cast<size_t>(b) * kHQ + h) * kD + d] = __float2half(acc);
}

// ---------------------------------------------------------------------------
// Device runner shared by --run and --bench
// ---------------------------------------------------------------------------

cudaError_t LaunchDecodeAttn(const void* q, const void* k, const void* v, void* o,
                             int batch, int kv_len, bool use_fp16) {
    const int grid = batch * kHQ;
    if (grid <= 0) return cudaSuccess;
    const size_t smem_bytes = static_cast<size_t>(kv_len) * sizeof(float);
    if (use_fp16) {
        DecodeAttnF16Kernel<<<grid, kThreads, smem_bytes>>>(
            static_cast<const __half*>(q), static_cast<const __half*>(k),
            static_cast<const __half*>(v), static_cast<__half*>(o),
            batch, kv_len);
    } else {
        DecodeAttnF32Kernel<<<grid, kThreads, smem_bytes>>>(
            static_cast<const float*>(q), static_cast<const float*>(k),
            static_cast<const float*>(v), static_cast<float*>(o),
            batch, kv_len);
    }
    return cudaGetLastError();
}

// ---------------------------------------------------------------------------
// Host-side CPU reference (selftest only)
// ---------------------------------------------------------------------------

void CpuDecodeAttnF32(const std::vector<float>& q, const std::vector<float>& k,
                      const std::vector<float>& v, int batch, int kv_len,
                      std::vector<float>& o) {
    o.assign(static_cast<size_t>(batch) * kHQ * kD, 0.0f);
    for (int b = 0; b < batch; ++b) {
        for (int h = 0; h < kHQ; ++h) {
            const int kv = h / 2;
            const float* qh = &q[(static_cast<size_t>(b) * kHQ + h) * kD];
            std::vector<float> s(kv_len);
            float s_max = -INFINITY;
            for (int t = 0; t < kv_len; ++t) {
                const float* kt = &k[((static_cast<size_t>(b) * kHKV + kv) * kv_len + t) * kD];
                float dot = 0.0f;
                for (int d = 0; d < kD; ++d) dot += qh[d] * kt[d];
                s[t] = kScale * dot;
                s_max = fmaxf(s_max, s[t]);
            }
            float sum = 0.0f;
            for (int t = 0; t < kv_len; ++t) {
                s[t] = expf(s[t] - s_max);
                sum += s[t];
            }
            float* oh = &o[(static_cast<size_t>(b) * kHQ + h) * kD];
            for (int d = 0; d < kD; ++d) oh[d] = 0.0f;
            for (int t = 0; t < kv_len; ++t) {
                const float p = s[t] / sum;
                const float* vt = &v[((static_cast<size_t>(b) * kHKV + kv) * kv_len + t) * kD];
                for (int d = 0; d < kD; ++d) oh[d] += p * vt[d];
            }
        }
    }
}

void CpuDecodeAttnF16(const std::vector<float>& q_f, const std::vector<float>& k_f,
                      const std::vector<float>& v_f, int batch, int kv_len,
                      std::vector<__half>& o) {
    std::vector<__half> q(q_f.size()), k(k_f.size()), v(v_f.size());
    for (size_t i = 0; i < q_f.size(); ++i) q[i] = __float2half(q_f[i]);
    for (size_t i = 0; i < k_f.size(); ++i) k[i] = __float2half(k_f[i]);
    for (size_t i = 0; i < v_f.size(); ++i) v[i] = __float2half(v_f[i]);
    o.assign(static_cast<size_t>(batch) * kHQ * kD, __float2half(0.0f));
    for (int b = 0; b < batch; ++b) {
        for (int h = 0; h < kHQ; ++h) {
            const int kv = h / 2;
            const __half* qh = &q[(static_cast<size_t>(b) * kHQ + h) * kD];
            std::vector<float> s(kv_len);
            float s_max = -INFINITY;
            for (int t = 0; t < kv_len; ++t) {
                const __half* kt = &k[((static_cast<size_t>(b) * kHKV + kv) * kv_len + t) * kD];
                float dot = 0.0f;
                for (int d = 0; d < kD; ++d) {
                    dot += __half2float(qh[d]) * __half2float(kt[d]);
                }
                s[t] = kScale * dot;
                s_max = fmaxf(s_max, s[t]);
            }
            float sum = 0.0f;
            for (int t = 0; t < kv_len; ++t) {
                s[t] = expf(s[t] - s_max);
                sum += s[t];
            }
            __half* oh = &o[(static_cast<size_t>(b) * kHQ + h) * kD];
            for (int d = 0; d < kD; ++d) oh[d] = __float2half(0.0f);
            for (int t = 0; t < kv_len; ++t) {
                const float p = s[t] / sum;
                const __half* vt = &v[((static_cast<size_t>(b) * kHKV + kv) * kv_len + t) * kD];
                for (int d = 0; d < kD; ++d) {
                    oh[d] = __float2half(__half2float(oh[d]) + p * __half2float(vt[d]));
                }
            }
        }
    }
}

int CountMismatchesF32(const std::vector<float>& a, const std::vector<float>& b,
                       float tol) {
    int bad = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        if (std::fabs(a[i] - b[i]) > tol || std::isnan(a[i]) != std::isnan(b[i])) ++bad;
    }
    return bad;
}

int CountMismatchesF16(const std::vector<__half>& a, const std::vector<__half>& b,
                       float tol) {
    int bad = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        const float fa = __half2float(a[i]);
        const float fb = __half2float(b[i]);
        if (std::fabs(fa - fb) > tol || std::isnan(fa) != std::isnan(fb)) ++bad;
    }
    return bad;
}

// ---------------------------------------------------------------------------
// File IO
// ---------------------------------------------------------------------------

bool ReadBinFile(const std::string& path, size_t expected_elems, size_t elem_size,
                 std::vector<uint8_t>& out) {
    FILE* f = std::fopen(path.c_str(), "rb");
    if (!f) {
        std::fprintf(stderr, "[ai_decode_attn] cannot open file '%s'\n", path.c_str());
        return false;
    }
    std::fseek(f, 0, SEEK_END);
    const long bytes = std::ftell(f);
    std::fseek(f, 0, SEEK_SET);
    if (bytes < 0 || static_cast<size_t>(bytes) != expected_elems * elem_size) {
        std::fprintf(stderr,
                     "[ai_decode_attn] file '%s' size mismatch: got %ld bytes, "
                     "expected %zu (%zu elems x %zu B)\n",
                     path.c_str(), bytes, expected_elems * elem_size,
                     expected_elems, elem_size);
        std::fclose(f);
        return false;
    }
    out.resize(static_cast<size_t>(bytes));
    const size_t got = std::fread(out.data(), 1, out.size(), f);
    std::fclose(f);
    if (got != out.size()) {
        std::fprintf(stderr, "[ai_decode_attn] short read on '%s'\n", path.c_str());
        return false;
    }
    return true;
}

bool WriteBinFile(const std::string& path, const void* data, size_t bytes) {
    FILE* f = std::fopen(path.c_str(), "wb");
    if (!f) {
        std::fprintf(stderr, "[ai_decode_attn] cannot open output file '%s'\n", path.c_str());
        return false;
    }
    if (bytes != 0) {
        if (std::fwrite(data, 1, bytes, f) != bytes) {
            std::fprintf(stderr, "[ai_decode_attn] short write on '%s'\n", path.c_str());
            std::fclose(f);
            return false;
        }
    }
    std::fclose(f);
    return true;
}

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

struct Args {
    std::string mode;
    long batch = -1, kv_len = -1;
    std::string dtype;
    std::string q_path, k_path, v_path, out_path;
    long warmup = -1, repeats = -1;
};

bool ParseArgs(int argc, char** argv, Args& a) {
    for (int i = 1; i < argc; ++i) {
        const std::string tok = argv[i];
        auto next_string = [&](std::string& dst) -> bool {
            if (i + 1 >= argc) {
                std::fprintf(stderr, "[ai_decode_attn] missing value for %s\n", tok.c_str());
                return false;
            }
            dst = argv[++i];
            return true;
        };
        auto next_long = [&](long& dst) -> bool {
            if (i + 1 >= argc) {
                std::fprintf(stderr, "[ai_decode_attn] missing value for %s\n", tok.c_str());
                return false;
            }
            dst = std::strtol(argv[++i], nullptr, 10);
            return true;
        };
        if (tok == "--selftest") a.mode = "selftest";
        else if (tok == "--run") a.mode = "run";
        else if (tok == "--bench") a.mode = "bench";
        else if (tok == "--batch") { if (!next_long(a.batch)) return false; }
        else if (tok == "--kv-len") { if (!next_long(a.kv_len)) return false; }
        else if (tok == "--dtype") { if (!next_string(a.dtype)) return false; }
        else if (tok == "--q") { if (!next_string(a.q_path)) return false; }
        else if (tok == "--k") { if (!next_string(a.k_path)) return false; }
        else if (tok == "--v") { if (!next_string(a.v_path)) return false; }
        else if (tok == "--out") { if (!next_string(a.out_path)) return false; }
        else if (tok == "--warmup") { if (!next_long(a.warmup)) return false; }
        else if (tok == "--repeats") { if (!next_long(a.repeats)) return false; }
        else {
            std::fprintf(stderr, "[ai_decode_attn] unknown argument '%s'\n", tok.c_str());
            return false;
        }
    }
    if (a.mode.empty()) {
        std::fprintf(stderr,
                     "usage: ai_decode_attn --selftest\n"
                     "       ai_decode_attn --run --batch B --kv-len N --dtype fp32|fp16 "
                     "--q q.bin --k k.bin --v v.bin --out o.bin\n"
                     "       ai_decode_attn --bench --batch B --kv-len N --dtype fp32|fp16 "
                     "--warmup W --repeats R\n");
        return false;
    }
    return true;
}

int RunMode(const Args& a) {
    if (a.batch < 0 || a.kv_len < 0) {
        std::fprintf(stderr, "[ai_decode_attn] --run requires --batch and --kv-len\n");
        return 2;
    }
    if (a.dtype != "fp32" && a.dtype != "fp16") {
        std::fprintf(stderr, "[ai_decode_attn] unsupported dtype '%s'\n", a.dtype.c_str());
        return 2;
    }
    if (a.batch <= 0 || a.kv_len <= 0) {
        std::fprintf(stderr, "[ai_decode_attn] invalid shape: batch=%ld kv_len=%ld "
                             "(both must be >= 1)\n", a.batch, a.kv_len);
        return 2;
    }
    const bool fp16 = (a.dtype == "fp16");
    const size_t elem_size = fp16 ? 2 : 4;
    const int batch = static_cast<int>(a.batch);
    const int kv_len = static_cast<int>(a.kv_len);
    const size_t qn = static_cast<size_t>(batch) * kHQ * kD;
    const size_t kvn = static_cast<size_t>(batch) * kHKV * kv_len * kD;

    std::vector<uint8_t> q_bytes, k_bytes, v_bytes;
    if (!ReadBinFile(a.q_path, qn, elem_size, q_bytes)) return 2;
    if (!ReadBinFile(a.k_path, kvn, elem_size, k_bytes)) return 2;
    if (!ReadBinFile(a.v_path, kvn, elem_size, v_bytes)) return 2;

    void *d_q = nullptr, *d_k = nullptr, *d_v = nullptr, *d_o = nullptr;
    const size_t q_bytes_n = qn * elem_size;
    const size_t kv_bytes_n = kvn * elem_size;
    if (cudaMalloc(&d_q, q_bytes_n) != cudaSuccess ||
        cudaMalloc(&d_k, kv_bytes_n) != cudaSuccess ||
        cudaMalloc(&d_v, kv_bytes_n) != cudaSuccess ||
        cudaMalloc(&d_o, q_bytes_n) != cudaSuccess) {
        std::fprintf(stderr, "[ai_decode_attn] cudaMalloc failed: %s\n",
                     cudaGetErrorString(cudaGetLastError()));
        return 1;
    }
    if (cudaMemcpy(d_q, q_bytes.data(), q_bytes_n, cudaMemcpyHostToDevice) != cudaSuccess ||
        cudaMemcpy(d_k, k_bytes.data(), kv_bytes_n, cudaMemcpyHostToDevice) != cudaSuccess ||
        cudaMemcpy(d_v, v_bytes.data(), kv_bytes_n, cudaMemcpyHostToDevice) != cudaSuccess) {
        std::fprintf(stderr, "[ai_decode_attn] cudaMemcpy H2D failed: %s\n",
                     cudaGetErrorString(cudaGetLastError()));
        return 1;
    }
    const cudaError_t launch_err =
        LaunchDecodeAttn(d_q, d_k, d_v, d_o, batch, kv_len, fp16);
    if (launch_err != cudaSuccess) {
        std::fprintf(stderr, "[ai_decode_attn] kernel launch failed: %s\n",
                     cudaGetErrorString(launch_err));
        return 1;
    }
    std::vector<uint8_t> o_bytes(q_bytes_n);
    if (cudaMemcpy(o_bytes.data(), d_o, q_bytes_n, cudaMemcpyDeviceToHost) != cudaSuccess) {
        std::fprintf(stderr, "[ai_decode_attn] cudaMemcpy D2H failed: %s\n",
                     cudaGetErrorString(cudaGetLastError()));
        return 1;
    }
    if (!WriteBinFile(a.out_path, o_bytes.data(), o_bytes.size())) return 1;
    cudaFree(d_q);
    cudaFree(d_k);
    cudaFree(d_v);
    cudaFree(d_o);
    return 0;
}

int BenchMode(const Args& a) {
    if (a.batch < 0 || a.kv_len < 0) {
        std::fprintf(stderr, "[ai_decode_attn] --bench requires --batch and --kv-len\n");
        return 2;
    }
    if (a.dtype != "fp32" && a.dtype != "fp16") {
        std::fprintf(stderr, "[ai_decode_attn] unsupported dtype '%s'\n", a.dtype.c_str());
        return 2;
    }
    if (a.batch <= 0 || a.kv_len <= 0) {
        std::fprintf(stderr, "[ai_decode_attn] invalid shape: batch=%ld kv_len=%ld "
                             "(both must be >= 1)\n", a.batch, a.kv_len);
        return 2;
    }
    if (a.warmup < 0 || a.repeats <= 0) {
        std::fprintf(stderr, "[ai_decode_attn] --bench requires --warmup and --repeats\n");
        return 2;
    }
    const bool fp16 = (a.dtype == "fp16");
    const size_t elem_size = fp16 ? 2 : 4;
    const int batch = static_cast<int>(a.batch);
    const int kv_len = static_cast<int>(a.kv_len);
    const size_t qn = static_cast<size_t>(batch) * kHQ * kD;
    const size_t kvn = static_cast<size_t>(batch) * kHKV * kv_len * kD;

    void *d_q = nullptr, *d_k = nullptr, *d_v = nullptr, *d_o = nullptr;
    const size_t q_bytes_n = qn * elem_size;
    const size_t kv_bytes_n = kvn * elem_size;
    if (cudaMalloc(&d_q, q_bytes_n) != cudaSuccess ||
        cudaMalloc(&d_k, kv_bytes_n) != cudaSuccess ||
        cudaMalloc(&d_v, kv_bytes_n) != cudaSuccess ||
        cudaMalloc(&d_o, q_bytes_n) != cudaSuccess) {
        std::fprintf(stderr, "[ai_decode_attn] cudaMalloc failed: %s\n",
                     cudaGetErrorString(cudaGetLastError()));
        return 1;
    }
    if (cudaMemset(d_q, 0, q_bytes_n) != cudaSuccess ||
        cudaMemset(d_k, 0, kv_bytes_n) != cudaSuccess ||
        cudaMemset(d_v, 0, kv_bytes_n) != cudaSuccess) {
        std::fprintf(stderr, "[ai_decode_attn] cudaMemset failed: %s\n",
                     cudaGetErrorString(cudaGetLastError()));
        return 1;
    }

    cudaEvent_t ev_start, ev_stop;
    if (cudaEventCreate(&ev_start) != cudaSuccess ||
        cudaEventCreate(&ev_stop) != cudaSuccess) {
        std::fprintf(stderr, "[ai_decode_attn] cudaEventCreate failed: %s\n",
                     cudaGetErrorString(cudaGetLastError()));
        return 1;
    }
    for (long i = 0; i < a.warmup; ++i) {
        if (LaunchDecodeAttn(d_q, d_k, d_v, d_o, batch, kv_len, fp16) != cudaSuccess) {
            std::fprintf(stderr, "[ai_decode_attn] warmup launch failed: %s\n",
                         cudaGetErrorString(cudaGetLastError()));
            return 1;
        }
    }
    for (long i = 0; i < a.repeats; ++i) {
        cudaEventRecord(ev_start);
        if (LaunchDecodeAttn(d_q, d_k, d_v, d_o, batch, kv_len, fp16) != cudaSuccess) {
            std::fprintf(stderr, "[ai_decode_attn] timed launch failed: %s\n",
                         cudaGetErrorString(cudaGetLastError()));
            return 1;
        }
        cudaEventRecord(ev_stop);
        float ms = 0.0f;
        cudaEventSynchronize(ev_stop);
        cudaEventElapsedTime(&ms, ev_start, ev_stop);
        std::printf("time_ms %.6f\n", ms);
    }
    std::printf("summary warmup=%ld repeats=%ld\n", a.warmup, a.repeats);
    cudaDeviceSynchronize();
    cudaEventDestroy(ev_start);
    cudaEventDestroy(ev_stop);
    cudaFree(d_q);
    cudaFree(d_k);
    cudaFree(d_v);
    cudaFree(d_o);
    return 0;
}

int SelfTest() {
    struct Case { int batch, kv_len; bool fp16; };
    const Case cases[] = {
        {2, 64, false},  {1, 63, false},  {1, 127, false}, {2, 100, false},
        {1, 512, false}, {2, 64, true},   {1, 63, true},   {1, 127, true},
        {2, 100, true},  {1, 512, true},
    };
    unsigned rng = 20261121u;
    auto next_uniform = [&rng](float lo, float hi) {
        rng = rng * 1664525u + 1013904223u;
        return lo + (hi - lo) * (static_cast<float>(rng & 0xffffff) / 16777216.0f);
    };

    for (const Case& c : cases) {
        const size_t qn = static_cast<size_t>(c.batch) * kHQ * kD;
        const size_t kvn = static_cast<size_t>(c.batch) * kHKV * c.kv_len * kD;
        std::vector<float> q(qn), k(kvn), v(kvn);
        for (size_t i = 0; i < qn; ++i) q[i] = next_uniform(-1.0f, 1.0f);
        for (size_t i = 0; i < kvn; ++i) k[i] = next_uniform(-1.0f, 1.0f);
        for (size_t i = 0; i < kvn; ++i) v[i] = next_uniform(-1.0f, 1.0f);

        const size_t elem_size = c.fp16 ? 2 : 4;
        void *d_q = nullptr, *d_k = nullptr, *d_v = nullptr, *d_o = nullptr;
        if (cudaMalloc(&d_q, qn * elem_size) != cudaSuccess ||
            cudaMalloc(&d_k, kvn * elem_size) != cudaSuccess ||
            cudaMalloc(&d_v, kvn * elem_size) != cudaSuccess ||
            cudaMalloc(&d_o, qn * elem_size) != cudaSuccess) {
            std::fprintf(stderr, "[selftest] cudaMalloc failed: %s\n",
                         cudaGetErrorString(cudaGetLastError()));
            return 1;
        }
        int bad = 0;
        if (c.fp16) {
            std::vector<__half> qh(qn), kh(kvn), vh(kvn), oh_dev, oh_ref;
            for (size_t i = 0; i < qn; ++i) qh[i] = __float2half(q[i]);
            for (size_t i = 0; i < kvn; ++i) kh[i] = __float2half(k[i]);
            for (size_t i = 0; i < kvn; ++i) vh[i] = __float2half(v[i]);
            cudaMemcpy(d_q, qh.data(), qn * 2, cudaMemcpyHostToDevice);
            cudaMemcpy(d_k, kh.data(), kvn * 2, cudaMemcpyHostToDevice);
            cudaMemcpy(d_v, vh.data(), kvn * 2, cudaMemcpyHostToDevice);
            LaunchDecodeAttn(d_q, d_k, d_v, d_o, c.batch, c.kv_len, true);
            cudaDeviceSynchronize();
            oh_dev.resize(qn);
            cudaMemcpy(oh_dev.data(), d_o, qn * 2, cudaMemcpyDeviceToHost);
            CpuDecodeAttnF16(q, k, v, c.batch, c.kv_len, oh_ref);
            bad = CountMismatchesF16(oh_dev, oh_ref, 2e-2f);
        } else {
            std::vector<float> oh_dev, oh_ref;
            cudaMemcpy(d_q, q.data(), qn * 4, cudaMemcpyHostToDevice);
            cudaMemcpy(d_k, k.data(), kvn * 4, cudaMemcpyHostToDevice);
            cudaMemcpy(d_v, v.data(), kvn * 4, cudaMemcpyHostToDevice);
            LaunchDecodeAttn(d_q, d_k, d_v, d_o, c.batch, c.kv_len, false);
            cudaDeviceSynchronize();
            oh_dev.resize(qn);
            cudaMemcpy(oh_dev.data(), d_o, qn * 4, cudaMemcpyDeviceToHost);
            CpuDecodeAttnF32(q, k, v, c.batch, c.kv_len, oh_ref);
            bad = CountMismatchesF32(oh_dev, oh_ref, 1e-4f);
        }
        std::printf("[selftest] %s batch=%d kv_len=%d mismatches=%d\n",
                    c.fp16 ? "fp16" : "fp32", c.batch, c.kv_len, bad);
        if (bad != 0) {
            std::printf("SELFTEST FAIL\n");
            return 1;
        }
        cudaFree(d_q);
        cudaFree(d_k);
        cudaFree(d_v);
        cudaFree(d_o);
    }
    std::printf("SELFTEST PASS\n");
    return 0;
}

}  // namespace

int main(int argc, char** argv) {
    Args a;
    if (!ParseArgs(argc, argv, a)) return 2;
    if (a.mode == "selftest") return SelfTest();
    if (a.mode == "run") return RunMode(a);
    if (a.mode == "bench") return BenchMode(a);
    return 2;
}
